window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2a30ea9a040585a2"]={"versions": [{"id": "FIG-2a30ea9a040585a2", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR-Spezifikation des Manifests (Adaptive Platform). Das Diagramm spezifiziert die Metamodell-Struktur für ein Executable und dessen strukturelle Einbettung über Komponenten-Prototypen in den Software-Komponententyp.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Executable</code> (Stereotypen <code>ARElement</code>, <code>AtpClassifier</code>): Repräsentiert das ausführbare Artefakt. Es deklariert die Attribute <code>buildType: BuildTypeEnum [0..1]</code>, <code>minimumTimerGranularity: TimeValue [0..1]</code> und <code>version: String [0..1]</code>.\n</li><li><code>RootSwComponentPrototype</code> (Stereotypen <code>AtpPrototype</code>, <code>Identifiable</code>): Repräsentiert die Wurzelinstanz einer Software-Komponente innerhalb des Executables.\n</li><li><code>SwComponentType</code> (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Repräsentiert den Typ der zugrundeliegenden Software-Komponente.\n</li><li>Komposition: <code>Executable</code> aggregiert per Komposition die Rolle <code>+rootSwComponentPrototype</code> mit Multiplizität <code>0..1</code> auf <code>RootSwComponentPrototype</code>.\n</li><li>Typisierungsbeziehung: <code>RootSwComponentPrototype</code> verweist über die gerichtete Assoziation <code>«isOfType»</code> mit Rollenname <code>+applicationType</code>, Multiplizität <code>1</code> und Eigenschaft <code>{redefines atpType}</code> auf <code>SwComponentType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellierung. Es beschreibt keine dynamischen Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge, sondern statische Kompositions- und Typisierungsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>Executable</code> kann optional genau einen <code>RootSwComponentPrototype</code> aggregieren (<code>0..1</code>). Sofern vorhanden, muss dieser Prototyp zwingend über <code>+applicationType</code> an genau einen <code>SwComponentType</code> gebunden sein (<code>1</code>). Die Versionierung erfolgt über ein generisches String-Attribut (<code>version: String [0..1]</code>), während <code>buildType</code> und minimale Timer-Granularität optional konfigurierbar sind.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-012fe9e4172c8207", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR-Spezifikation des Manifests (Adaptive Platform). Das Diagramm spezifiziert die Metamodell-Struktur für ein Executable und dessen strukturelle Einbettung über Komponenten-Prototypen in den Software-Komponententyp.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Executable</code> (Stereotypen <code>ARElement</code>, <code>AtpClassifier</code>): Repräsentiert das ausführbare Artefakt. Es deklariert die Attribute <code>buildType: BuildTypeEnum [0..1]</code>, <code>minimumTimerGranularity: TimeValue [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>.\n</li><li><code>RootSwComponentPrototype</code> (Stereotypen <code>AtpPrototype</code>, <code>Identifiable</code>): Repräsentiert die Wurzelinstanz einer Software-Komponente innerhalb des Executables.\n</li><li><code>SwComponentType</code> (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Repräsentiert den Typ der zugrundeliegenden Software-Komponente.\n</li><li>Komposition: <code>Executable</code> aggregiert per Komposition die Rolle <code>+rootSwComponentPrototype</code> mit Multiplizität <code>0..1</code> auf <code>RootSwComponentPrototype</code>.\n</li><li>Typisierungsbeziehung: <code>RootSwComponentPrototype</code> verweist über die gerichtete Assoziation <code>«isOfType»</code> mit Rollenname <code>+applicationType</code>, Multiplizität <code>1</code> und Eigenschaft <code>{redefines atpType}</code> auf <code>SwComponentType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellierung. Es beschreibt keine dynamischen Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge, sondern statische Kompositions- und Typisierungsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>Executable</code> kann optional genau einen <code>RootSwComponentPrototype</code> aggregieren (<code>0..1</code>). Sofern vorhanden, muss dieser Prototyp zwingend über <code>+applicationType</code> an genau einen <code>SwComponentType</code> gebunden sein (<code>1</code>). Die Versionierung erfordert das Format <code>StrongRevisionLabelString</code> (<code>version [0..1]</code>), womit Revisionsbezeichner formal validiert werden können. <code>buildType</code> und minimale Timer-Granularität sind optional konfigurierbar.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-21cb531a82c6d2f7", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR-Spezifikation des Manifests (Adaptive Platform). Das Diagramm spezifiziert die Metamodell-Struktur für ein Executable und dessen strukturelle Einbettung über Komponenten-Prototypen in den Software-Komponententyp.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Executable</code> (Stereotypen <code>ARElement</code>, <code>AtpClassifier</code>): Repräsentiert das ausführbare Artefakt. Es deklariert die Attribute <code>buildType: BuildTypeEnum [0..1]</code>, <code>loggingBehavior: LoggingBehaviorEnum [0..1]</code>, <code>minimumTimerGranularity: TimeValue [0..1]</code>, <code>reportingBehavior: ExecutionStateReportingBehaviorEnum [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>.\n</li><li><code>RootSwComponentPrototype</code> (Stereotypen <code>AtpPrototype</code>, <code>Identifiable</code>): Repräsentiert die Wurzelinstanz einer Software-Komponente innerhalb des Executables.\n</li><li><code>SwComponentType</code> (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Repräsentiert den Typ der zugrundeliegenden Software-Komponente.\n</li><li>Komposition: <code>Executable</code> aggregiert per Komposition die Rolle <code>+rootSwComponentPrototype</code> mit Multiplizität <code>0..1</code> auf <code>RootSwComponentPrototype</code>.\n</li><li>Typisierungsbeziehung: <code>RootSwComponentPrototype</code> verweist über die gerichtete Assoziation <code>«isOfType»</code> mit Rollenname <code>+applicationType</code>, Multiplizität <code>1</code> und Eigenschaft <code>{redefines atpType}</code> auf <code>SwComponentType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellierung. Es beschreibt keine dynamischen Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge, sondern statische Kompositions- und Typisierungsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>Executable</code> modelliert Konfigurationsparameter für Logging und Ausführungszustands-Meldung über <code>loggingBehavior</code> (<code>LoggingBehaviorEnum</code>) und <code>reportingBehavior</code> (<code>ExecutionStateReportingBehaviorEnum</code>). Es kann optional genau einen <code>RootSwComponentPrototype</code> enthalten (<code>0..1</code>), der wiederum an genau einen typisierenden <code>SwComponentType</code> gebunden sein muss (<code>1</code>). Versionierungsangaben folgen <code>StrongRevisionLabelString</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-aca758de79505fb7", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR-Spezifikation des Manifests (Adaptive Platform). Das Diagramm spezifiziert die Metamodell-Struktur für ein Executable und dessen strukturelle Einbettung über Komponenten-Prototypen in den Software-Komponententyp.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen, Datentypen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Executable</code> (Stereotypen <code>ARElement</code>, <code>AtpClassifier</code>): Repräsentiert das ausführbare Artefakt mit den Attributen <code>buildType: BuildTypeEnum [0..1]</code>, <code>loggingBehavior: LoggingBehaviorEnum [0..1]</code>, <code>minimumTimerGranularity: TimeValue [0..1]</code>, <code>reportingBehavior: ExecutionStateReportingBehaviorEnum [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>.\n</li><li><code>LoggingBehaviorEnum</code> (<code>«enumeration»</code>): Definiert die Literale <code>usesLogging</code> und <code>doesNotUseLogging</code>.\n</li><li><code>ExecutionStateReportingBehaviorEnum</code> (<code>«enumeration»</code>): Definiert die Literale <code>reportsExecutionState</code> und <code>doesNotReportExecutionState</code>.\n</li><li><code>RootSwComponentPrototype</code> (Stereotypen <code>AtpPrototype</code>, <code>Identifiable</code>): Repräsentiert die Wurzelinstanz einer Software-Komponente innerhalb des Executables.\n</li><li><code>SwComponentType</code> (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Repräsentiert den Typ der zugrundeliegenden Software-Komponente.\n</li><li>Komposition: <code>Executable</code> aggregiert per Komposition die Rolle <code>+rootSwComponentPrototype</code> mit Multiplizität <code>0..1</code> auf <code>RootSwComponentPrototype</code>.\n</li><li>Typisierungsbeziehung: <code>RootSwComponentPrototype</code> verweist über die gerichtete Assoziation <code>«isOfType»</code> mit Rollenname <code>+applicationType</code>, Multiplizität <code>1</code> und Eigenschaft <code>{redefines atpType}</code> auf <code>SwComponentType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellierung. Es beschreibt keine dynamischen Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge, sondern statische Kompositions- und Typisierungsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für <code>Executable</code> ist explizit festgelegt, welche Werte die Verhaltensattribute annehmen können: <code>loggingBehavior</code> kann auf <code>usesLogging</code> oder <code>doesNotUseLogging</code> gesetzt werden, <code>reportingBehavior</code> auf <code>reportsExecutionState</code> oder <code>doesNotReportExecutionState</code>. Ein aggregierter <code>RootSwComponentPrototype</code> (<code>0..1</code>) bindet das Executable an genau einen <code>SwComponentType</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-21e2158c23671c33", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR-Spezifikation des Manifests (Adaptive Platform). Das Diagramm spezifiziert die Metamodell-Struktur für ein Executable und dessen strukturelle Einbettung über Komponenten-Prototypen in den Software-Komponententyp.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen, Datentypen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Executable</code> (Stereotypen <code>ARElement</code>, <code>AtpClassifier</code>): Repräsentiert das ausführbare Artefakt mit den Attributen <code>buildType: BuildTypeEnum [0..1]</code>, <code>loggingBehavior: LoggingBehaviorEnum [0..1]</code>, <code>minimumTimerGranularity: TimeValue [0..1]</code>, <code>reportingBehavior: ExecutionStateReportingBehaviorEnum [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>.\n</li><li><code>LoggingBehaviorEnum</code> (<code>«enumeration»</code>): Definiert die Literale <code>usesLogging</code> und <code>doesNotUseLogging</code>.\n</li><li><code>ExecutionStateReportingBehaviorEnum</code> (<code>«enumeration»</code>): Definiert die Literale <code>reportsExecutionState</code> und <code>doesNotReportExecutionState</code>.\n</li><li><code>RootSwComponentPrototype</code> (Stereotypen <code>AtpPrototype</code>, <code>Identifiable</code>): Repräsentiert die Wurzelinstanz einer Software-Komponente innerhalb des Executables.\n</li><li><code>SwComponentType</code> (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Repräsentiert den Typ der zugrundeliegenden Software-Komponente.\n</li><li>Komposition: <code>Executable</code> aggregiert per Komposition die Rolle <code>+rootSwComponentPrototype</code> mit Multiplizität <code>0..1</code> auf <code>RootSwComponentPrototype</code>.\n</li><li>Typisierungsbeziehung: <code>RootSwComponentPrototype</code> verweist über die gerichtete Assoziation <code>«isOfType»</code> mit Rollenname <code>+applicationType</code>, Multiplizität <code>1</code> und Eigenschaft <code>{redefines atpType}</code> auf <code>SwComponentType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellierung. Es beschreibt keine dynamischen Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge, sondern statische Kompositions- und Typisierungsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für <code>Executable</code> ist explizit festgelegt, welche Werte die Verhaltensattribute annehmen können: <code>loggingBehavior</code> kann auf <code>usesLogging</code> oder <code>doesNotUseLogging</code> gesetzt werden, <code>reportingBehavior</code> auf <code>reportsExecutionState</code> oder <code>doesNotReportExecutionState</code>. Ein aggregierter <code>RootSwComponentPrototype</code> (<code>0..1</code>) bindet das Executable an genau einen <code>SwComponentType</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-46c7a026af449e64", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR-Spezifikation des Manifests (Adaptive Platform). Das Diagramm fokussiert isoliert auf die Metaklasse Executable und ihre Ausführungsmeldekonfiguration.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Datentypen:</p>\n<ul class=\"fig-list\"><li><code>Executable</code> (Stereotypen <code>ARElement</code>, <code>AtpClassifier</code>): Repräsentiert das ausführbare Artefakt. Es deklariert die Attribute <code>buildType: BuildTypeEnum [0..1]</code>, <code>minimumTimerGranularity: TimeValue [0..1]</code>, <code>reportingBehavior: ExecutionStateReportingBehaviorEnum [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>.\n</li><li><code>ExecutionStateReportingBehaviorEnum</code> (<code>«enumeration»</code>): Definiert die Ausprägungen <code>reportsExecutionState</code> und <code>doesNotReportExecutionState</code>.\n</li><li>Es bestehen keine Assoziationen oder Kompositionsbeziehungen zu Komponentenprototypen oder Komponententypen im Diagramm.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellierung. Es beschreibt keine dynamischen Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge, sondern statische Kompositions- und Typisierungsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung von <code>Executable</code> umfasst Ausführungsmeldeeinstellungen über <code>reportingBehavior: ExecutionStateReportingBehaviorEnum [0..1]</code>. Das Logging-Verhalten sowie direkte Assoziationen zu Software-Komponentenprototypen werden im Diagramm nicht mehr an <code>Executable</code> geführt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-86d2b76c2ccff795", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR-Spezifikation des Manifests (Adaptive Platform). Das Diagramm fokussiert isoliert auf die Metaklasse Executable und ihre Ausführungsmeldekonfiguration.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Datentypen:</p>\n<ul class=\"fig-list\"><li><code>Executable</code> (Stereotypen <code>AtpClassifier</code>, <code>UploadableDesignElement</code>): Repräsentiert das ausführbare Artefakt. Es deklariert die Attribute <code>buildType: BuildTypeEnum [0..1]</code>, <code>minimumTimerGranularity: TimeValue [0..1]</code>, <code>reportingBehavior: ExecutionStateReportingBehaviorEnum [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>.\n</li><li><code>ExecutionStateReportingBehaviorEnum</code> (<code>«enumeration»</code>): Definiert die Ausprägungen <code>reportsExecutionState</code> und <code>doesNotReportExecutionState</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellierung. Es beschreibt keine dynamischen Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge, sondern statische Kompositions- und Typisierungsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>Executable</code> ist als <code>UploadableDesignElement</code> klassifiziert und dient damit als ladbares Designelement im System. Die Verhaltenssteuerung bezüglich des Ausführungszustands erfolgt über <code>reportingBehavior</code> mit den Werten <code>reportsExecutionState</code> bzw. <code>doesNotReportExecutionState</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-411ca6468fa39df2", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR-Spezifikation des Manifests (Adaptive Platform). Das Diagramm fokussiert isoliert auf die Metaklasse Executable und ihre Ausführungsmeldekonfiguration.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Datentypen:</p>\n<ul class=\"fig-list\"><li><code>Executable</code> (Stereotypen <code>AtpClassifier</code>, <code>UploadableDesignElement</code>): Repräsentiert das ausführbare Artefakt. Es deklariert die Attribute <code>buildType: BuildTypeEnum [0..1]</code>, <code>minimumTimerGranularity: TimeValue [0..1]</code>, <code>reportingBehavior: ExecutionStateReportingBehaviorEnum [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>.\n</li><li><code>ExecutionStateReportingBehaviorEnum</code> (<code>«enumeration»</code>): Definiert die Ausprägungen <code>reportsExecutionState</code> und <code>doesNotReportExecutionState</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellierung. Es beschreibt keine dynamischen Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge, sondern statische Kompositions- und Typisierungsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>Executable</code> ist als <code>UploadableDesignElement</code> klassifiziert und dient damit als ladbares Designelement im System. Die Verhaltenssteuerung bezüglich des Ausführungszustands erfolgt über <code>reportingBehavior</code> mit den Werten <code>reportsExecutionState</code> bzw. <code>doesNotReportExecutionState</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-980c63c2afb663fc", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR-Spezifikation des Manifests (Adaptive Platform). Das Diagramm fokussiert auf die Metaklasse Executable sowie die zugehörigen Enumerationen zur Laufzeit- und Suspend-to-RAM-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Datentypen:</p>\n<ul class=\"fig-list\"><li><code>Executable</code> (Stereotypen <code>AtpClassifier</code>, <code>UploadableDesignElement</code>): Repräsentiert das ausführbare Artefakt. Es deklariert die Attribute <code>minimumTimerGranularity: TimeValue [0..1]</code>, <code>reportingBehavior: ExecutionStateReportingBehaviorEnum [0..1]</code>, <code>suspendToRamAwareness: SuspendToRamAwarenessEnum [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>.\n</li><li><code>ExecutionStateReportingBehaviorEnum</code> (<code>«enumeration»</code>): Definiert die Literale <code>reportsExecutionState</code> und <code>doesNotReportExecutionState</code>.\n</li><li><code>SuspendToRamAwarenessEnum</code> (<code>«enumeration»</code>): Definiert die Literale <code>suspendToRamTolerant</code>, <code>suspendToRamNotSupported</code> und <code>suspendToRamAware</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellierung. Es beschreibt keine dynamischen Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge, sondern statische Kompositions- und Typisierungsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>Executable</code> ist als <code>UploadableDesignElement</code> klassifiziert und dient damit als ladbares Designelement im System. Neben der Verhaltenssteuerung bezüglich der Ausführungszustandsmeldung über <code>reportingBehavior</code> (<code>reportsExecutionState</code>, <code>doesNotReportExecutionState</code>) wird über <code>suspendToRamAwareness</code> das Verhalten bezüglich des Suspend-to-RAM-Modus (<code>suspendToRamTolerant</code>, <code>suspendToRamNotSupported</code>, <code>suspendToRamAware</code>) festgelegt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2a30ea9a040585a2", "to": "FIG-012fe9e4172c8207", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In der Klasse <code>Executable</code> wurde der Datentyp des Attributs <code>version</code> von <code>String</code> auf <code>StrongRevisionLabelString</code> geändert.\n</li></ul>"}, {"from": "FIG-012fe9e4172c8207", "to": "FIG-21cb531a82c6d2f7", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In der Klasse <code>Executable</code> wurden die Attribute <code>loggingBehavior: LoggingBehaviorEnum [0..1]</code> und <code>reportingBehavior: ExecutionStateReportingBehaviorEnum [0..1]</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-21cb531a82c6d2f7", "to": "FIG-aca758de79505fb7", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Das Diagramm wurde um die expliziten Deklarationen der Aufzählungstypen <code>«enumeration» LoggingBehaviorEnum</code> (Literale: <code>usesLogging</code>, <code>doesNotUseLogging</code>) und <code>«enumeration» ExecutionStateReportingBehaviorEnum</code> (Literale: <code>reportsExecutionState</code>, <code>doesNotReportExecutionState</code>) oberhalb der Klasse <code>Executable</code> ergänzt.\n</li></ul>"}, {"from": "FIG-aca758de79505fb7", "to": "FIG-21e2158c23671c33", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-21e2158c23671c33", "to": "FIG-46c7a026af449e64", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In der Klasse <code>Executable</code> wurde das Attribut <code>loggingBehavior: LoggingBehaviorEnum [0..1]</code> entfernt.\n</li><li>Die Aufzählung <code>«enumeration» LoggingBehaviorEnum</code> wurde aus dem Diagramm entfernt.\n</li><li>Die Komposition von <code>Executable</code> zu <code>RootSwComponentPrototype</code> (<code>rootSwComponentPrototype [0..1]</code>) sowie das Zielelement <code>RootSwComponentPrototype</code> wurden entfernt.\n</li><li>Die Assoziation <code>applicationType</code> (<code>«isOfType»</code>, Multiplizität 1, <code>{redefines atpType}</code>) sowie das Zielelement <code>SwComponentType</code> wurden entfernt.\n</li><li>Das Diagrammlayout wurde von einer vertikalen Hierarchie auf eine horizontale Anordnung von <code>Executable</code> und <code>ExecutionStateReportingBehaviorEnum</code> umgestellt.\n</li></ul>"}, {"from": "FIG-46c7a026af449e64", "to": "FIG-86d2b76c2ccff795", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In der Klassendeklaration von <code>Executable</code> wurde der Stereotyp bzw. die Metaklassenspezifikation <code>ARElement</code> durch <code>UploadableDesignElement</code> ersetzt.\n</li></ul>"}, {"from": "FIG-86d2b76c2ccff795", "to": "FIG-411ca6468fa39df2", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>In <code>ExecutionStateReportingBehaviorEnum</code> wurde die Abschnittsüberschrift <code>literals</code> über den Literalwerten eingefügt.\n</li></ul>"}, {"from": "FIG-411ca6468fa39df2", "to": "FIG-980c63c2afb663fc", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In <code>Executable</code> entfällt das Attribut <code>buildType: BuildTypeEnum [0..1]</code>.\n</li><li>In <code>Executable</code> wird das Attribut <code>suspendToRamAwareness: SuspendToRamAwarenessEnum [0..1]</code> ergänzt.\n</li><li>Die Enumeration <code>SuspendToRamAwarenessEnum</code> mit den Literalen <code>suspendToRamTolerant</code>, <code>suspendToRamNotSupported</code> und <code>suspendToRamAware</code> wird neu hinzugefügt.\n</li></ul>"}]};
